"""From the session transcript: the 420-passed run's file list, the live acceptance runs, the
commits, and every write to src/ or tests/ after 17:40 UTC (timestamps and paths only)."""
import json, re, sys

uses = {}
events = []
for line in open(sys.argv[1]):
    try:
        entry = json.loads(line)
    except json.JSONDecodeError:
        continue
    ts = entry.get("timestamp", "?")
    content = (entry.get("message") or {}).get("content")
    if not isinstance(content, list):
        continue
    for block in content:
        if block.get("type") == "tool_use":
            name, inp = block.get("name"), block.get("input") or {}
            uses[block["id"]] = (name, inp)
            if name in ("Edit", "Write") and re.search(r"/(src|tests)/", inp.get("file_path", "")) and ts >= "2026-10-23T17:40":
                events.append((ts, f"{name} {inp['file_path'].split('worker-pipeline/')[-1]}"))
            elif name == "Bash":
                cmd = inp.get("command", "")
                if ts >= "2026-10-23T17:40" and re.search(r"(src/etf_risk|tests/)\S*\.py", cmd) and re.search(r"write_text|sed -i|cat >>?|patch |\.replace\(", cmd):
                    files = sorted(set(re.findall(r"(?:src/etf_risk|tests)/[\w/]+\.py", cmd)))
                    events.append((ts, "Bash write? " + ", ".join(files)))
                if "git commit" in cmd and ts >= "2026-10-23T17:00":
                    events.append((ts, "COMMIT " + re.sub(r"\s+", " ", cmd)[:110]))
        elif block.get("type") == "tool_result" and block.get("tool_use_id") in uses:
            name, inp = uses[block["tool_use_id"]]
            if name != "Bash":
                continue
            cmd = inp.get("command", "")
            text = block.get("content")
            if isinstance(text, list):
                text = "\n".join(p.get("text", "") for p in text if isinstance(p, dict))
            text = str(text)
            if "420 passed" in text and "pytest" in cmd:
                files = re.findall(r"tests/\S+\.py", cmd)
                events.append((ts, f"RUN 420 passed over {len(files)} files: " + " ".join(f.split('/')[-1] for f in files)))
            if "ETF_RISK_LIVE_PIPELINE" in cmd and "pytest" in cmd:
                summary = [l.strip() for l in text.splitlines() if re.search(r"\b\d+ (passed|failed)", l) and len(l) < 200]
                if summary:
                    events.append((ts, "LIVE PIPELINE RUN -> " + summary[-1]))
for ts, what in sorted(events):
    print(ts[:19], what)
EOF
